{
  "command": "cd /mnt/c/Users/cabot/OneDrive/Documents/Research/Cambridge/X3I/mhd_llm/claude/src/mhd && python3 - <<'EOF'
p='helio.cu'
s=open(p).read()
s=s.replace('''    float s = 0.f, vm = 0.f;
    if (id < n) {''','''    float s = 0.f, vm = 0.f, gx = 0.f;
    if (id < n) {''')
s=s.replace('''            s += (fabsf(vn) + c) / hx[d];
            vm = fmaxf(vm, fabsf(vn) + c);
        }
    }
    for (int o = 16; o > 0; o >>= 1) {
        s = fmaxf(s, __shfl_down_sync(0xffffffff, s, o));
        vm = fmaxf(vm, __shfl_down_sync(0xffffffff, vm, o));
    }
    if ((threadIdx.x & 31) == 0) {
        atomicMax(out, __float_as_uint(s));
        atomicMax(out + 1, __float_as_uint(vm));
    }''','''            s += (fabsf(vn) + c) / hx[d];
            gx += 1.f / hx[d];
            vm = fmaxf(vm, fabsf(vn) + c);
        }
    }
    for (int o = 16; o > 0; o >>= 1) {
        s = fmaxf(s, __shfl_down_sync(0xffffffff, s, o));
        vm = fmaxf(vm, __shfl_down_sync(0xffffffff, vm, o));
        gx = fmaxf(gx, __shfl_down_sync(0xffffffff, gx, o));
    }
    if ((threadIdx.x & 31) == 0) {
        atomicMax(out, __float_as_uint(s));
        atomicMax(out + 1, __float_as_uint(vm));
        atomicMax(out + 2, __float_as_uint(gx));
    }''')
s=s.replace('''        CK(cudaMemset(d_red, 0, 8));
        k_dt<<<nblk(nc), TB>>>(U0, d_rc, d_tc, d_pc, d_red);
        unsigned red[2];
        CK(cudaMemcpy(red, d_red, 8, cudaMemcpyDeviceToHost));
        float smax, vmax;
        memcpy(&smax, &red[0], 4);
        memcpy(&vmax, &red[1], 4);''','''        CK(cudaMemset(d_red, 0, 12));
        k_dt<<<nblk(nc), TB>>>(U0, d_rc, d_tc, d_pc, d_red);
        unsigned red[3];
        CK(cudaMemcpy(red, d_red, 12, cudaMemcpyDeviceToHost));
        float smax, vmax, gmax;
        memcpy(&smax, &red[0], 4);
        memcpy(&vmax, &red[1], 4);
        memcpy(&gmax, &red[2], 4);''')
s=s.replace('''        chv = vmax;''','''        chv = std::min((double)vmax, ch_frac * smax / gmax);''')
s=s.replace('''    double cfl = dget("cfl", 0.8), damp_a = dget("glm_alpha", 0.3);''','''    double cfl = dget("cfl", 0.8), damp_a = dget("glm_alpha", 0.3), ch_frac = dget("ch_frac", 0.95);''')
open(p,'w').write(s)
EOF
make helio 2>&1 | grep -i error; cd ../../bench; for v in "solver=0 cfl=0.8" "solver=0 cfl=0.6"; do tag=$(echo $v | tr ' =' '__'); mkdir -p out_sphere/dbg/c$tag; ../src/mhd/helio out_sphere/spc_256x60x120/cfg.txt $v out_dir=out_sphere/dbg/c$tag t_end_s=400000 diag_dt_s=50000 > out_sphere/dbg/c$tag/stdout.txt 2>&1; echo "== $v"; tail -2 out_sphere/dbg/c$tag/stdout.txt; grep divb out_sphere/dbg/c$tag/log.txt | awk '{print $1, $4, $5}' | tail -3; done",
